	if(mdc_codizyzd.includes("DI_L00")) return "L";
	if(mdc_codizyzd.includes("DI_M00")&&xb==1) return "M";
	if(mdc_codizyzd.includes("DI_N00")&&xb==2) return "N";
	if(mdc_codizyzd.includes("DI_O00")) return "O";
	if(mdc_codizyzd.includes("DI_Q00")) return "Q";
