function Intersection(arr1,arr2){
	//判断arr1中是否含有arr2中的元素 判断是否有交集
	return arr1.some(e=>arr2.includes(e));
};

function incl(arr,x){
	 return arr.includes(x);
};
function sp(x){
	try{ return x.split(",")}catch{return null }
};

function chsdrg(txt1,txt2,nl,xsrtl,xb,xsrtz){
    let zyzd=[];
    let qtzd=[];
    let zyss=[];
    let qtss=[];
    let cc_content=[];
    let arr1=sp(txt1)?? [];
    let arr2=sp(txt2)?? [];
    let exc;
    arr1.forEach((e,i)=>{
        e=icd10_content[e]?? e;
        if(i==0) {zyzd=sp(collection_directory[e])?? [];exc=exclude_table[e];};
        if(i!=0){
            qtzd.push(sp(collection_directory[e])??[]);
            let cc=sp(cc_table[e]);
            if(cc!=null&&cc[0]!=exc){
                cc_content.push(cc[1]);
            }
        }
    });
    if(arr2.length!=0){
        arr2.forEach((e,i)=>{
            e=icd9_content[e]?? e
            if(i==0) zyss=sp(collection_directory[e])??[];
            if(i!=0) qtss.push(sp(collection_directory[e])??[]);
        });
    };
    qtzd=qtzd.flat();
    qtss=qtss.flat();

    let mdc=mdc_condition(zyzd,qtzd,zyss,qtss,nl,xsrtl,xb);
    let adrg=adrg_condition(mdc,zyzd,qtzd,zyss,qtss,nl,xsrtl,xb,xsrtz);
    let drg_txt=drg_condition(adrg,cc_content,nl,zyzd,zyss,qtss);
    return [drg_txt,drg_tabal[drg_txt]];
};
